/**
 * Step 2 — Upload RDF (Turtle) into Fuseki
 *
 * What this script does:
 * 1. Reads the Turtle file from app/db/imports/imports.ttl (generated by script 1).
 * 2. Sends it to your local Fuseki dataset (history/data) with HTTP POST.
 * 3. Uses basic auth (admin:admin) as required by Fuseki for uploads.
 * 4. Prints success or error so you see what happened.
 *
 * Requirements: Fuseki running at http://127.0.0.1:3030/history/ (e.g. Docker).
 */

const fs = require("fs");
const path = require("path");

const FUSEKI_DATA_URL = "http://127.0.0.1:3030/history/data";
const AUTH = Buffer.from("admin:admin").toString("base64");
const TTL_PATH = path.join(process.cwd(), "app", "db", "imports", "imports.ttl");

async function main() {
  console.log("Uploading RDF to Fuseki...\n");
  console.log("File:", TTL_PATH);
  console.log("Endpoint:", FUSEKI_DATA_URL);
  console.log("Auth: admin (basic auth)\n");

  if (!fs.existsSync(TTL_PATH)) {
    console.error("Error: File not found:", TTL_PATH);
    process.exit(1);
  }

  const ttl = fs.readFileSync(TTL_PATH, "utf8");

  const response = await fetch(FUSEKI_DATA_URL, {
    method: "POST",
    headers: {
      "Content-Type": "text/turtle",
      Authorization: `Basic ${AUTH}`,
    },
    body: ttl,
  });

  if (!response.ok) {
    const text = await response.text();
    console.error("Upload failed. Status:", response.status, response.statusText);
    console.error("Response:", text || "(empty)");
    process.exit(1);
  }

  const body = await response.text();
  console.log("Upload successful.");
  if (body) console.log("Response:", body.trim());
  console.log("\nRun script 3 (verify-fuseki) to list wars in the database.");
}

main().catch((err) => {
  console.error("Error:", err.message);
  process.exit(1);
});
